This is the **smart contract code** that handles the **payment**.  
```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract LemonadeStand {
    // Store the address of the lemonade seller
    address public seller;

    // Store the price of lemonade (in ETH)
    uint256 public price = 0.001 ether;

    // Constructor: Set the seller's address
    constructor(address _seller) {
        seller = _seller;
    }

    // Function: Buy lemonade
    function buyLemonade() public payable {
        require(msg.value >= price, "Not enough ETH!");
        // Transfer the payment to the seller
        (bool success, ) = payable(seller).call{value: msg.value}("");
        require(success, "Payment failed!");
        // Emit an event to signal the transaction
        emit LemonadeBought(msg.sender);
    }

